n, m = map(int, input().split())
a = []
for i in range(n):
    a.append(list(map(int, input().split())))
ans = 0
for u in range(n):
    for l in range(m):
        for d in range(u, n):
            chk = 1
            for r in range(l, m):
                for x in range(u, d + 1):
                    chk *= a[x][r]
                if not chk:
                    break
                ans = max(ans, (r - l + 1) * (d - u + 1))
print(ans)

n = int(input())
a = sorted(list(map(int, input().split())))
last, cnt, mx = a[0], 1, 1
for i in a:
    if last == i:
        continue
    if last + 1 == i:
        cnt += 1
    else:
        cnt = 1
    last = i
    mx = max(mx, cnt)
print(mx)
